/* GitHub */
const repoPath=()=>{const m=S.cfg.repo.match(/([\w.-]+)\/([\w.-]+?)(?:\.git)?\/?$/);if(!m)throw new Error('URL du dépôt invalide');return`/repos/${m[1]}/${m[2]}`};
const nice=e=>{const s=e.message;if(/rate limit/i.test(s))return'Trop de requêtes envoyées à GitHub : attends une minute puis réessaie.';if(s.startsWith('422'))return'GitHub a refusé la demande ('+s+'). Si ça persiste, fais un Pull puis réessaie.';return s.startsWith('401')?'Token invalide ou expiré.':s.startsWith('403')?'Permission refusée par GitHub ('+s.replace(/^403 /,'').replace(/ @.*$/,'')+'). Vérifie les permissions du token (Contents, et Workflows pour .github/workflows).':s.startsWith('404')?'Introuvable : vérifie le dépôt, la branche, et que le token a accès à ce dépôt. [étape : '+(s.split(' @')[1]||'?')+']':s.startsWith('409')?'Dépôt vide : rien à récupérer. Utilise Envoyer pour créer le premier commit.':s};
