const doCommit=msg=>{const{cur,ch}=status();if(!ch.length)return false;for(const p in cur)S.objs[cur[p]]=S.files[p];S.commits.push({id:hash(JSON.stringify(cur)+Date.now()).slice(0,7),msg,time:Date.now(),tree:cur});S.commits=S.commits.slice(-30);const keep=new Set();S.commits.forEach(c=>Object.values(c.tree).forEach(h=>keep.add(h)));for(const h in S.objs)if(!keep.has(h))delete S.objs[h];return true};

