const nodeHtml=(n,base,d)=>{let h='';const pd=`style="--d:${d}"`;for(const k of Object.keys(n.d).sort()){const p=base+k,c=S.collapsed.includes(p);h+=`<div class="fr" ${pd}><span class="nm" data-a="${sel?'pkd':'tog'}" data-v="${esc(p)}">${sel?`<i class="ck${isDirSel(p)?' on':''}"></i>`:`<i class="cv${c?'':' o'}">${ic('chev')}</i>`}${ic('folder','var(--ac)')}${esc(k)}</span><button class="m" data-a="md" data-v="${esc(p)}">${ic('more')}</button></div>`;if(!c)h+=nodeHtml(n.d[k],p+'/',d+1)}for(const p of n.f)h+=`<div class="fr${p===S.open?' sel':''}" ${pd}><span class="nm" data-a="${sel?'pk':'open'}" data-v="${esc(p)}">${sel?`<i class="ck${sel.has(p)?' on':''}"></i>`:'<i class="cv"></i>'}${ic('file',col(p))}${esc(p.split('/').pop())}</span><button class="m" data-a="mf" data-v="${esc(p)}">${ic('more')}</button></div>`;return h};
const rF=()=>{const root={d:{},f:[]},ks=Object.keys(S.files).sort();for(const p of ks){let n=root;for(const k of p.split('/').slice(0,-1))n=n.d[k]??={d:{},f:[]};n.f.push(p)}$('#p-f').innerHTML=sect('Explorateur',ks.length+' fichier'+(ks.length>1?'s':''))+`<div class="tiles">${tile('nf','fileplus','Fichier')}${tile('nd','folderplus','Dossier')}${tile('up','upload','Importer')}${tile('zi','zip','Import ZIP')}${tile('ze','download','Export ZIP')}${tile('sm','checksq','Sélection')}</div>`+(ks.length?`<div class="tree">${nodeHtml(root,'',0)}</div>`:'<p class="mu empty">Aucun fichier. Crée un fichier ou importe un ZIP pour commencer.</p>')};
const rG=()=>{const{ch}=status();$('#p-g').innerHTML=sect('Contrôle de source',ch.length+' modif.')+`<input id="msg" placeholder="Message du commit"><div class="two"><button class="pr" data-a="com">${ic('check')}Valider</button><button data-a="sync">${ic('cloud')}Envoyer</button></div>`+sect('Modifications')+(ch.map(c=>`<div class="fr" data-a="dif" data-v="${esc(c[0])}"><span class="nm"><b class="bd ${c[1]}">${c[1]}</b>${esc(c[0])}</span></div>`).join('')||'<p class="mu empty">Rien à valider.</p>')+`<button class="sm" style="width:100%;margin:6px 0 10px" data-a="ghl">${ic('cloud')}Historique GitHub (versions déjà envoyées)</button>`+sect('Historique local',S.commits.length+'')+(S.commits.slice().reverse().map((c,i)=>`<div class="cm" data-a="cd" data-v="${S.commits.length-1-i}"><div><b>${esc(c.msg)}</b><small class="mu">${c.id} · ${new Date(c.time).toLocaleString('fr-FR')}</small></div><button class="sm" data-a="rst" data-v="${S.commits.length-1-i}">Restaurer</button></div>`).join('')||'<p class="mu empty">Aucun commit.</p>')};
const rH=()=>{const rp=S.cfg.repo.match(/([\w.-]+\/[\w.-]+?)(?:\.git)?\/?$/);$('#p-h').innerHTML=sect('GitHub')+`<div class="grp"><label>Token</label><input id="tk" type="password" placeholder="Colle ton token GitHub" value="${esc(S.cfg.token)}"></div><div class="rcard">${ic('git')}<div><b>${rp?esc(rp[1]):'Aucun dépôt choisi'}</b><small class="mu">Branche ${esc(S.cfg.branch)}</small></div><button data-a="repos">Choisir</button></div><input id="rp" placeholder="ou colle l’URL du dépôt" value="${esc(S.cfg.repo)}"><input id="br" placeholder="Branche" value="${esc(S.cfg.branch)}"><div class="tiles">${tile('pull','download','Pull')}${tile('push','upload','Push')}${tile('tst','check','Tester')}${tile('site','globe','Lien de test')}${tile('nrepo','folderplus','Nouveau dépôt')}${tile('vis','globe','Public / Privé')}</div><pre id="ghs" class="mu"></pre><p class="mu">Token « fine-grained » : permission Contents en lecture et écriture, Metadata en lecture. Pour créer des dépôts et passer en public/privé : permission Administration en lecture et écriture, avec accès à tous les dépôts (ou token classique avec « repo » et « workflow »).</p>`};
const rC=()=>{const st=S.set,ths=[['cyan','#22d3ee'],['clair','#d12f35'],['rouge','#f0545a'],['vert','#34d27b'],['bleu','#4c94f5'],['violet','#9b73f5'],['ambre','#f0a82a']],row=(l,c)=>`<div class="ro"><span>${l}</span>${c}</div>`;$('#p-c').innerHTML=sect('Paramètres')+'<div class="grp"><label>Apparence</label><div class="chips">'+ths.map(([t,c])=>`<button class="chip${S.theme===t?' on':''}" data-a="th" data-v="${t}"><i style="background:${c}"></i>${t[0].toUpperCase()+t.slice(1)}</button>`).join('')+'</div></div><div class="grp"><label>Éditeur</label>'+row('Taille du texte',`<div class="step"><button data-a="fs" data-v="-1">−</button><b>${st.fs}</b><button data-a="fs" data-v="1">+</button></div>`)+row('Retour à la ligne',sw('tg','wrap',st.wrap))+row('Numéros de ligne',sw('tg','ln',st.ln))+row('Indentation',`<button class="sm" data-a="tg" data-v="tab">${st.tab} espaces</button>`)+'</div><div class="grp"><label>Intelligence artificielle</label>'+row('Fonctions IA (Gemini)',sw('aiTg','on',S.ai.on))+(S.ai.on?`<input id="gk" type="password" placeholder="Clé API Gemini" value="${esc(S.ai.key)}"><input id="gm" placeholder="Modèle" value="${esc(S.ai.model)}">`+row('Gemini voit mon projet',sw('aiTg','ctx',S.ai.ctx))+row('Lecture vocale automatique',sw('aiTg','auto',S.ai.auto))+`<button data-a="aiTest">${ic('check')}Tester la clé</button><p class="mu">Clé gratuite : aistudio.google.com. Les .env, clés privées et tokens ne sont jamais envoyés.</p>`:'')+'</div><div class="grp"><label>Compte</label><button data-a="tab" data-v="h">'+ic('cloud')+'Configurer GitHub</button><button class="danger" data-a="wipe">'+ic('trash')+'Vider l’espace de travail</button></div><p class="mu">CodePocket 1.6</p>'};
const rHome=()=>{const h=$('#home');h.classList.add('on');const av=n=>{let x=0;for(const c of n)x=(x*31+c.charCodeAt(0))%360;return`hsl(${x} 55% 45%)`};h.innerHTML=`<div class="hw"><div class="hd"><div class="lg">${ic('term')}</div><div><h1>CodePocket</h1><p class="mu">Ton code. Tes projets. Ton GitHub.</p></div></div><div class="stats"><div><small>GitHub</small><b>${S.cfg.token?'Connecté':'Non connecté'}</b></div><div><small>Projets</small><b>${S.index.length}</b></div><div><small>Stockage</small><b id="stg">…</b></div></div>${sect('Actions rapides')}<div class="tiles">${tile('np','folderplus','Nouveau')}${tile('cl','git','Cloner')}${tile('zn','zip','Import ZIP')}${tile('lp','book','Apprendre')}${tile('tm','term','Terminal')}${tile('st','gear','Paramètres')}${S.ai.on?tile('ai0','spark','Gemini'):''}</div>${sect('Projets',S.index.length+'')}${S.index.slice().sort((a,b)=>b.mtime-a.mtime).map(p=>`<div class="pj" data-a="op" data-v="${p.id}"><i class="av" style="background:${av(p.name)}">${esc((p.name[0]||'?').toUpperCase())}</i><div><b>${esc(p.name)}</b><small class="mu">${esc(p.repo?p.repo.replace(/^https?:\/\/github\.com\//,''):'Local')} · ${esc(p.branch||'main')}</small><small class="mu">${new Date(p.mtime).toLocaleString('fr-FR')}${p.n?' · '+p.n+' modif.':''}</small></div><button class="m" data-a="pm" data-v="${p.id}">${ic('more')}</button></div>`).join('')||'<p class="mu empty">Aucun projet. Crée-en un ou clone un dépôt.</p>'}${S.cur?`<button class="back" data-a="back">${ic('back')}Retour au projet</button>`:''}</div>`;navigator.storage?.estimate?.().then(e=>{const x=$('#stg');if(x)x.textContent=(e.usage/1048576).toFixed(0)+' Mo'})};
