const showViewer=p=>{const f=S.files[p],ext=p.split('.').pop().toLowerCase(),mt={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',bmp:'image/bmp',ico:'image/x-icon',avif:'image/avif',mp4:'video/mp4',webm:'video/webm',mov:'video/quicktime',m4v:'video/mp4','3gp':'video/3gpp',mp3:'audio/mpeg',wav:'audio/wav',ogg:'audio/ogg',m4a:'audio/mp4',aac:'audio/aac'}[ext],u8=Uint8Array.from(atob(f.b),c=>c.charCodeAt(0)),kb=u8.length>1048576?(u8.length/1048576).toFixed(1)+' Mo':(u8.length/1024).toFixed(0)+' Ko',v=$('#viewer');if(vurl){URL.revokeObjectURL(vurl);vurl=null}v.classList.add('on');if(!mt){v.innerHTML=`<div class="vi"><h3>${esc(p.split('/').pop())}</h3><p class="mu">${kb}. Aperçu non disponible pour ce type de fichier.</p></div>`;return}vurl=URL.createObjectURL(new Blob([u8],{type:mt}));v.innerHTML=`<div class="vi">${mt.startsWith('image')?`<img src="${vurl}">`:mt.startsWith('video')?`<video src="${vurl}" controls playsinline></video>`:`<audio src="${vurl}" controls></audio>`}<p class="mu">${esc(p.split('/').pop())} · ${kb}</p></div>`};
