const lintHtml=t=>{const out=[],ln=i=>t.slice(0,i).split('\n').length,st=[];let m;const re=/<!--[\s\S]*?-->|<(\/?)([A-Za-z][\w:.-]*)((?:"[^"]*"|'[^']*'|[^<>"'])*)>/g;while(m=re.exec(t)){if(m[0].startsWith('<!--'))continue;const cl=m[1]==='/',nm=m[2].toLowerCase(),at=m[3];if(!cl){for(const a of at.matchAll(/([\w:@-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g)){const v=a[2]??a[3];if(v!==v.trim())out.push('Ligne '+ln(m.index)+' : espace en trop dans la valeur de « '+a[1]+' » (« '+v+' »). Le fichier ou lien ne sera pas trouvé.')}if(/("|')[A-Za-z_:@-][\w:-]*\s*=/.test(at.replace(/\s/g,m2=>m2)) && /("[^"]*"|'[^']*')[A-Za-z_:@-]/.test(at))out.push('Ligne '+ln(m.index)+' : il manque un espace entre deux attributs.');if(nm==='img'&&!/\balt\s*=/.test(at))out.push('Ligne '+ln(m.index)+' : l’image n’a pas de texte alternatif (alt).');if(VOID.has(nm)||/\/\s*$/.test(at))continue;if(nm==='script'||nm==='style'){const e=t.toLowerCase().indexOf('</'+nm,re.lastIndex);if(e>0)re.lastIndex=e;}st.push([nm,m.index])}else{if(VOID.has(nm))continue;const i=st.map(x=>x[0]).lastIndexOf(nm);if(i<0)out.push('Ligne '+ln(m.index)+' : </'+nm+'> n’a pas de balise ouvrante.');else{for(const x of st.splice(i).slice(1))out.push('Ligne '+ln(x[1])+' : <'+x[0]+'> n’est jamais fermée.')}}}for(const x of st)out.push('Ligne '+ln(x[1])+' : <'+x[0]+'> n’est jamais fermée.');return out};
